using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BORepair {
 public static object MotorBenches(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string e="Assets/Afrer_Seconds/05.Model/Environment/B2/",p="Assets/Afrer_Seconds/05.Model/Props/B2/";var mats=AssetDatabase.FindAssets("t:Material",new[]{e+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));mats["B2M_Plate"]=mats["B4O_Plate"];foreach(string suffix in new[]{"","_LOD1"}){var mi=(ModelImporter)AssetImporter.GetAtPath(p+"BO_MotorServiceBench"+suffix+".fbx");mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();}
 var all=GameObject.Find("B2_OperationsLayout").GetComponentsInChildren<Transform>();int count=0;foreach(var t in all.Where(t=>t.name.StartsWith("B2_S01_Ops_DiagnosticBench_")||t.name=="B2_W03_Ops_Repair_07"||t.name=="B2_W03_Ops_Repair_09")){foreach(var mf in t.GetComponentsInChildren<MeshFilter>()){bool low=mf.transform!=t;var src=AssetDatabase.LoadAssetAtPath<GameObject>(p+"BO_MotorServiceBench"+(low?"_LOD1":"")+".fbx");mf.sharedMesh=src.GetComponent<MeshFilter>().sharedMesh;mf.GetComponent<MeshRenderer>().sharedMaterials=src.GetComponent<MeshRenderer>().sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(mf.GetComponent<MeshRenderer>());}count++;}foreach(var t in all.Where(t=>t.name.Contains("_Ops_RepairMotors_")||t.name.Contains("_Ops_TestMotors_"))){t.localScale=Vector3.one*.65f;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}AssetDatabase.SaveAssets();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{motorBenches=count};}
 public static object TaskLighting(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(r+"/SourceAssets/B2_OperationsRebuild/plan.json"));string path="Assets/Afrer_Seconds/05.Model/Environment/B2/Materials/BO_TaskLens.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BO_TaskLens"};mat.SetColor("_BaseColor",new Color(.8f,.18f,.055f));mat.SetColor("_EmissionColor",new Color(1,.25f,.075f)*1.6f);mat.EnableKeyword("_EMISSION");AssetDatabase.CreateAsset(mat,path);}foreach(var room in plan["rooms"]){string id=(string)room["id"];var g=GameObject.Find("B2_"+id+"_Pendant_0");var l=g.GetComponentInChildren<Light>();l.color=new Color(1,.30f,.14f);l.intensity=7.4f;l.range=(float)room["r"]*1.5f;foreach(var mr in g.GetComponentsInChildren<MeshRenderer>()){mr.sharedMaterials=mr.sharedMaterials.Select(m=>m&&m.name.Contains("RedLens")?mat:m).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(mr);}PrefabUtility.RecordPrefabInstancePropertyModifications(l);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{taskFixtures=12,addedLights=0};}
 public static object Diagnose(){string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var plan=JObject.Parse(File.ReadAllText(r+"/SourceAssets/B2_OperationsRebuild/plan.json"));var tests=JArray.Parse(File.ReadAllText(r+"/Docs/Review/2026-11-10_B2_Operations/upper.json"));return tests.SelectMany(t=>t["moves"].Where(m=>!(bool)m["passed"]).Select(m=>{var q=m["position"];var p=new Vector3((float)q[0],(float)q[1],(float)q[2]);float h=(float)plan["routes"].Single(v=>(string)v["name"]==(string)t["name"])["height"];return new{name=(string)t["name"],position=p.ToString(),hits=Physics.OverlapCapsule(p+Vector3.up*.32f,p+Vector3.up*(h-.30f),.33f).Select(c=>new{c.name,asset=c is MeshCollider?AssetDatabase.GetAssetPath(((MeshCollider)c).sharedMesh):"",size=c.bounds.size.ToString()}).ToArray()};})).ToArray();}
 public static object Placements(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");var h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_OperationsRebuild/"));var plan=JObject.Parse(File.ReadAllText(h+"plan.json"));int count=0;foreach(var p in plan["placements"]){var g=GameObject.Find((string)p["name"]);if(!g)continue;g.transform.localPosition=new Vector3((float)p["position"][0],(float)p["position"][1],(float)p["position"][2]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);if(PrefabUtility.IsPartOfPrefabInstance(g))PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);count++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{moved=count};}
}
